(15825, 5080, 3, 717, '2023-09-15 02:44:25', 'Error: Ink Box Full\r\nAction taken: Reset ink box. done\r\n\r\nProcedure: \r\n\r\n1. Press \"Menu+Mono+Menu\"\r\n2. Press \"arrow up\", look for \"8\" then press \"ok\"\r\n3.Press \"arrow up\", look for \"0\" then press \"ok\"\r\n4. Press \"Mono\" look for \"Purge Count\" then press \"ok\"\r\n5. Press \"arrow up\", look for \"2\" then press \"ok\"\r\n6. Press \"arrow up\", look for \"7\" then press \"ok\"\r\n7. Press \"arrow up\", look for \"8\" then press \"ok\"\r\n8. Press \"arrow up\", look for \"3\" then press \"ok\"\r\n9. Restart the machine', NULL, 'Active', '', NULL, NULL, NULL, NULL, NULL),
(15826, 5080, 3, 717, '2023-09-15 02:44:25', 'Error: Ink Box Full\r\nAction taken: Reset ink box. done\r\n\r\nProcedure: \r\n\r\n1. Press \"Menu+Mono+Menu\"\r\n2. Press \"arrow up\", look for \"8\" then press \"ok\"\r\n3.Press \"arrow up\", look for \"0\" then press \"ok\"\r\n4. Press \"Mono\" look for \"Purge Count\" then press \"ok\"\r\n5. Press \"arrow up\", look for \"2\" then press \"ok\"\r\n6. Press \"arrow up\", look for \"7\" then press \"ok\"\r\n7. Press \"arrow up\", look for \"8\" then press \"ok\"\r\n8. Press \"arrow up\", look for \"3\" then press \"ok\"\r\n9. Restart the machine', NULL, 'Active', '', NULL, NULL, NULL, NULL, NULL),
